import flet as ft
from services.sprite_selector import sheet_selector, sprite_selector
from components.sheet_sprite import sheet_sprite

# Out-of-combat Idle pose: standing, facing front (clip generated by tools/ro_to_sheet.py)
STAND_CLIP = "stand_s"


def job_sprite(job: str, height: float):
    """Character standing and facing front on the selection/creation/profile screens.
    Uses the stand_s clip from the job's sheet; without a sheet, falls back to the old GIF."""
    sheet_name = sheet_selector(job)
    if sheet_name:
        return sheet_sprite(sheet_name, STAND_CLIP, height=height)

    gif = sprite_selector(job)
    if gif:
        return ft.Image(src=gif, height=height, fit=ft.BoxFit.CONTAIN)
    return ft.Container(height=height)
